cat > src/orchestration/chatOrchestrator.test.ts.patch << 'EOF'
--- src/orchestration/chatOrchestrator.test.ts
+++ src/orchestration/chatOrchestrator.test.ts
@@ -512,4 +512,45 @@
     expect(seen).toEqual(usage);
   });
+
+  /** @spec specs/hal-engine-tool-input-validation/spec.md#3 */
+  it('returns a schema rejection as a tool_result in the orchestrator loop so the model can correct the call on the next round', async () => {
+    let round = 0;
+    const sentMessages: SendMessageParams[] = [];
+    const provider: AIProvider = {
+      async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
+        sentMessages.push(params);
+        round++;
+        if (round === 1) {
+          yield {type: 'tool_use', toolCall: {id: 'call-1', name: 'lookup', input: {wrong: 'type'}}};
+          yield {type: 'stop', stopReason: 'tool_use'};
+        } else {
+          yield {type: 'text', text: 'the answer'};
+          yield {type: 'stop', stopReason: 'end_turn'};
+        }
+      },
+      async generateStructured<T>(): Promise<T> {
+        return {} as T;
+      },
+    };
+
+    const registry = new ToolRegistry();
+    let executorCalls = 0;
+    registry.register({
+      name: 'lookup',
+      description: 'lookup',
+      inputSchema: {type: 'object', properties: {q: {type: 'string'}}, required: ['q']}
+    }, async () => {
+      executorCalls++;
+      return 'found';
+    });
+
+    const orchestrator = createChatOrchestrator(provider, promptBuilder, registry);
+    await orchestrator.processMessage(createSession('ask'));
+
+    expect(executorCalls).toBe(0);
+    const secondRoundMessages = sentMessages[1]?.messages ?? [];
+    const lastMessage = secondRoundMessages[secondRoundMessages.length - 1];
+    expect(lastMessage).toMatchObject({
+      role: 'user',
+      content: [{type: 'tool_result', toolUseId: 'call-1', content: expect.stringContaining('Validation failed')}],
+    });
+  });
 });
EOF
patch src/orchestration/chatOrchestrator.test.ts < src/orchestration/chatOrchestrator.test.ts.patch

